{"items":[{"path":"tools.opencode.models","description":"Search the models available to use. Use this to turn a model name the user mentions into an exact reference for a tool that takes a model. Check your own provider first. Prefer the standard offering unless the user explicitly requests another tier. Use the listed pricing to compare costs when available; missing pricing does not mean free.","signature":"tools.opencode.models({
  /** Text to search for in model names and IDs. */
  query?: string,
  /** Provider ID or name to filter by. Try your own provider first. */
  provider?: string,
  /**
   * Which kind of model to list. Defaults to "chat".
   * "chat": a language model (LLM). Powers sessions, agents and subagents, and can call tools.
   * "image": generates or edits images from a prompt. It can't chat or call tools.
   * "video": generates videos from a prompt. It can't chat or call tools.
   */
  type?: "chat" | "image" | "video",
  /** Include older versions of each model family. By default only the newest version is listed. */
  all?: boolean,
  /** Maximum number of models to return. Defaults to 20. @integer @minimum 1 @maximum 100 */
  limit?: number,
  /** Number of models to skip, for paging through results. @integer @minimum 0 */
  offset?: number,
}): Promise<{
  /** Number of matching models across all pages. @integer */
  total: number,
  /** Offset of the next page, or null on the last page. */
  next: number | null,
  /** Matching models grouped by provider. Your own provider comes first. */
  providers: Array<{
      id: string,
      name: string,
      /** Newest first. */
      models: Array<{
          /** providerID/modelID */
          id: string,
          name: string,
          /** Release date as a Unix timestamp in milliseconds, or 0 when unknown. */
          released: number,
          variants: Array<string>,
          /** Pricing in USD per million tokens. */
          cost: Array<{
              tier?: {
                type: "context",
                /** @integer */
                size: number,
              },
              input: number,
              output: number,
              cache: {
                read: number,
                write: number,
              },
            }>,
          status: "alpha" | "beta" | "deprecated" | "active",
        }>,
    }>,
}>"},{"path":"tools.opencode.session.move","description":"Move a session to another directory, or omit sessionID to move the current session. The current session moves at the next safe boundary; do not run destination-dependent tools in the same execute call.","signature":"tools.opencode.session.move({
  /** Omit to move the current session. @pattern ^ses */
  sessionID?: string,
  /** Destination directory, relative to the target session's directory or absolute. Supports ~. @minLength 1 */
  directory: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  directory: string,
}>"},{"path":"tools.opencode.session.rename","description":"Rename a session, or omit sessionID to rename the current session. Use a short, specific title that summarizes the work being done.","signature":"tools.opencode.session.rename({
  /** Omit to rename the current session. @pattern ^ses */
  sessionID?: string,
  /** New session title. @minLength 1 */
  title: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  title: string,
}>"},{"path":"tools.opencode.worktree_create","description":"Create a named worktree. Returns its directory.","signature":"tools.opencode.worktree_create({
  name: string,
}): Promise<{
  directory: string,
}>"},{"path":"tools.opencode.worktree_list","description":"List a repository's worktrees.","signature":"tools.opencode.worktree_list(): Promise<{
  worktrees: Array<{
      directory: string,
      strategy?: string,
    }>,
}>"},{"path":"tools.opencode.worktree_remove","description":"Remove a worktree. The repository location selects configuration; directory identifies the worktree to remove.","signature":"tools.opencode.worktree_remove({
  /** Absolute path of the worktree to remove. @minLength 1 */
  directory: string,
  /** Discard modified and untracked files. Only set this when the user has confirmed forced removal. */
  force?: boolean,
}): Promise<{
  directory: string,
  removed: boolean,
}>"},{"path":"tools.opencode.list_mcp_events","description":"List the events an MCP server sends. Use one as an automation's event trigger.","signature":"tools.opencode.list_mcp_events({
  /** MCP server name as configured */
  server: string,
}): Promise<{
  events: Array<{
      server: string,
      event: string,
      description?: string | null,
      args?: {} | null,
      data?: {} | null,
    }>,
}>"},{"path":"tools.opencode.list_mcp_resources","description":"List documents, records, and other data exposed by MCP servers. Use this when the user refers to something that is not a local file, such as a URI with a custom scheme, then load a match with read_mcp_resource. Each entry names the server to read it from. Templates are resources addressed by a parameter such as a record ID; fill in the uriTemplate placeholders before reading.","signature":"tools.opencode.list_mcp_resources({
  /** MCP server name as configured. Omit to list every server. */
  server?: string,
}): Promise<{
  resources: Array<{
      server: string,
      name: string,
      uri: string,
      description?: string,
      mimeType?: string,
    }>,
