      name: string,
      uriTemplate: string,
      description?: string,
      mimeType?: string,
    }>,
}>"},{"path":"tools.opencode.read_mcp_resource","description":"Read one MCP resource by server and URI. Not for local files. Always return the full contents rather than slicing or filtering them; oversized output is truncated automatically and the full content is saved to a file you can read. Images and PDFs are shown to you directly.","signature":"tools.opencode.read_mcp_resource({
